/* frappe-ui forces `font-family: InterVar`, a face the desk doesn't load (it
   ships "Inter"/"InterVariable"), so it falls back to the system font. Point
   the panel at the desk's real fonts. */
.flow-panel {
	font-family: "Inter", "InterVariable", ui-sans-serif, system-ui, sans-serif;
	font-weight: 400;
}

/* Even vertical rhythm between an assistant message's blocks (text + tool cards).
   Text carries line-height half-leading that cards don't, so the boundary next
   to a text blob is tightened to keep all visual gaps equal. */
.flow-parts > * + * {
	margin-top: 10px;
}
/* a text blob followed by a tool/confirm card — extra breathing room below the text */
.flow-parts > .md + * {
	margin-top: calc(22px - 0.36em);
}
/* a card/element followed by a text blob */
.flow-parts > * + .md {
	margin-top: calc(10px - 0.36em);
}
.flow-parts > .md + .md {
	margin-top: calc(16px - 0.72em);
}

